/**
 * Image & Text Columns Block – Edit Component
 *
 * Image/video column + InnerBlocks text column.
 * Alignment, column widths, background, drop shadow.
 */

const { Fragment, useEffect } = wp.element;
const { InnerBlocks, InspectorControls, MediaUpload, useBlockProps } = wp.blockEditor;
const { PanelBody, SelectControl, ToggleControl, Button, ResponsiveWrapper } = wp.components;
const { __ } = wp.i18n;

import ImageComp from '../../components/ImageComp.js';
import BackgroundColor from '../../components/BackgroundColor.js';
import BackgroundSelector from '../../components/BackgroundSelector.js';
import ColumnsWidth from '../../components/ColumnsWidth.js';
import PaddingSelector from '../../components/Padding.js';
import MarginSelector from '../../components/Margin.js';
import BlobAnimation from '../../components/BlobAnimation.js';

const alignOptions = [
    { label: __( 'Image Left', 'red-egg' ), value: 'img-left' },
    { label: __( 'Image Right', 'red-egg' ), value: 'img-right' },
];

const VidImg = [
    { label: __( 'Image', 'red-egg' ), value: 'image' },
    { label: __( 'Video', 'red-egg' ), value: 'video' },
];

const template = [
    [ 'core/heading', { level: 2, placeholder: 'Section Header...' } ],
    [ 'core/paragraph', { placeholder: 'Section paragraph...' } ],
    [ 'core/buttons', {}, [
        [ 'core/button', { placeholder: 'CTA...' } ],
    ] ],
];

const allowBlocks = [
    'core/heading',
    'core/paragraph',
    'core/list',
    'core/buttons',
    'core/image',
    'core/spacer',
];

const EditImageText = ( { attributes, setAttributes, clientId } ) => {
    const {
        contentAlign, columnwidth, media, image, bgColor, bgSlug,
        vidOrImg, videoID, videoURL, videothumb,
        padding, margin, blockId,
        blobEnabled, blobShape, blobSpeed, blobPosition, squiggleEnabled,
    } = attributes;

    useEffect( () => {
        if ( ! blockId ) {
            setAttributes( { blockId: 'block-' + clientId } );
        }
    }, [] );

    const updateImageAttr = ( img ) => {
        let large = img.url;
        let medium = img.sizes && img.sizes['medium-small']
            ? img.sizes['medium-small'].url
            : img.url;

        setAttributes( {
            media: {
                srcSet: { large, medium },
                id: img.id,
                alt: img.alt,
            },
        } );
    };

    const updateVideoAttr = ( vid ) => {
        setAttributes( {
            videoURL: vid.url,
            videoID: vid.id,
        } );
    };

    const setVideoThumb = ( img ) => {
        let newThumb = JSON.parse( JSON.stringify( videothumb ) );
        newThumb.url = img.url;
        newThumb.width = img.width;
        newThumb.height = img.height;
        setAttributes( { videothumb: newThumb } );
    };

    const removeVideoThumb = () => {
        setAttributes( {
            videothumb: { url: '', width: '', height: '' },
        } );
    };

    // Build background styles
    const bgStyle = {};
    if ( image.url ) {
        bgStyle.backgroundImage = `url(${ image.url })`;
        bgStyle.backgroundRepeat = image.repeat || 'no-repeat';
        bgStyle.backgroundAttachment = image.attachment || 'scroll';
        bgStyle.backgroundSize = image.sizekey || 'cover';
        if ( image.bgkeyword === 'keyword' ) {
            bgStyle.backgroundPosition = image.position || 'center center';
        } else {
            const unit = image.bgunit || 'px';
            bgStyle.backgroundPosition = `${ image.positionX || 0 }${ unit } ${ image.positionY || 0 }${ unit }`;
        }
        if ( image.sizekey === '' && image.size ) {
            bgStyle.backgroundSize = `${ image.size }${ image.unit || '%' }`;
        }
    }

    const blockProps = useBlockProps( {
        id: blockId,
        className: 'image-columns'
            + ' ' + contentAlign
            + ' ' + columnwidth
            + ( bgSlug ? ' ' + bgSlug + ' with-bg' : '' )
            + ( blobEnabled ? ' has-blob' : '' )
            + ( squiggleEnabled ? ' has-squiggle' : '' ),
        style: bgStyle,
    } );

    return (
        <Fragment>
            <InspectorControls>
                <PanelBody
                    title={ __( 'Align Content', 'red-egg' ) }
                    initialOpen={ true }
                >
                    <SelectControl
                        label={ __( 'Align Content', 'red-egg' ) }
                        value={ contentAlign }
                        options={ alignOptions }
                        onChange={ ( val ) => setAttributes( { contentAlign: val } ) }
                    />
                </PanelBody>
                <ColumnsWidth
                    columnwidth={ columnwidth }
                    setAttributes={ setAttributes }
                />
                <BackgroundColor
                    bgColor={ bgColor }
                    bgSlug={ bgSlug }
                    setAttributes={ setAttributes }
                />
                { vidOrImg === 'image' && (
                    <BackgroundSelector
                        setAttributes={ setAttributes }
                        image={ image }
                    />
                ) }
                <PanelBody
                    title={ __( 'Video or Image', 'red-egg' ) }
                    initialOpen={ false }
                >
                    <SelectControl
                        label={ __( 'Video or Image', 'red-egg' ) }
                        value={ vidOrImg }
                        options={ VidImg }
                        onChange={ ( val ) => setAttributes( { vidOrImg: val } ) }
                    />
                </PanelBody>
                { vidOrImg === 'video' && (
                    <PanelBody
                        title={ __( 'Video Thumbnail', 'red-egg' ) }
                        initialOpen={ false }
                    >
                        <MediaUpload
                            allowedTypes={ [ 'image' ] }
                            onSelect={ setVideoThumb }
                            value={ videothumb.url }
                            render={ ( { open } ) => (
                                <Fragment>
                                    <Button
                                        isSecondary
                                        onClick={ open }
                                        style={ { marginBottom: '15px', height: 'auto', display: 'block', width: '100%' } }
                                    >
                                        { ! videothumb.url && __( 'Add Video Thumbnail', 'red-egg' ) }
                                        { videothumb.url && (
                                            <ResponsiveWrapper
                                                naturalWidth={ videothumb.width }
                                                naturalHeight={ videothumb.height }
                                            >
                                                <img src={ videothumb.url } style={ { maxHeight: 'auto', width: 'auto' } } alt="" />
                                            </ResponsiveWrapper>
                                        ) }
                                    </Button>
                                    { videothumb.url && (
                                        <Button isDestructive isSmall onClick={ removeVideoThumb }>
                                            { __( 'Remove Image', 'red-egg' ) }
                                        </Button>
                                    ) }
                                </Fragment>
                            ) }
                        />
                    </PanelBody>
                ) }
                <BlobAnimation.Controls
                    blobEnabled={ blobEnabled }
                    blobShape={ blobShape }
                    blobSpeed={ blobSpeed }
                    blobPosition={ blobPosition }
                    setAttributes={ setAttributes }
                />
                <PanelBody
                    title={ __( 'Squiggle Decoration', 'red-egg' ) }
                    initialOpen={ false }
                >
                    <ToggleControl
                        label={ __( 'Enable Squiggle Line', 'red-egg' ) }
                        checked={ !! squiggleEnabled }
                        onChange={ () => setAttributes( { squiggleEnabled: ! squiggleEnabled } ) }
                    />
                </PanelBody>
            </InspectorControls>

            <PaddingSelector
                padding={ padding }
                id={ 'block-' + clientId }
                setAttributes={ setAttributes }
            />
            <MarginSelector
                margin={ margin }
                id={ 'block-' + clientId }
                setAttributes={ setAttributes }
            />

            <div { ...blockProps }>
                
                <div className={ `block-wrapper ${ contentAlign }` }>
                <BlobAnimation.Preview
                    blobEnabled={ blobEnabled }
                    blobShape={ blobShape }
                    blobPosition={ blobPosition }
                />
                { squiggleEnabled && (
                    <div className="squiggle-decoration">
                        <svg className="squiggle-decoration__svg" width="196" height="29" viewBox="0 0 196 29" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M196 29C184.63 29 178.87 22.535 173.785 16.83C169.085 11.555 165.03 7 156.8 7C148.57 7 144.51 11.555 139.815 16.83C134.73 22.535 128.97 29 117.6 29C106.23 29 100.47 22.535 95.385 16.83C90.685 11.555 86.63 7 78.4 7C70.17 7 66.11 11.555 61.415 16.83C56.33 22.535 50.57 29 39.2 29C27.83 29 22.07 22.535 16.985 16.83C12.29 11.555 8.23 7 0 7V0C11.37 0 17.13 6.465 22.215 12.17C26.915 17.445 30.97 22 39.2 22C47.43 22 51.49 17.445 56.185 12.17C61.27 6.465 67.03 0 78.395 0C89.76 0 95.525 6.465 100.61 12.17C105.31 17.445 109.365 22 117.595 22C125.825 22 129.885 17.445 134.58 12.17C139.665 6.465 145.425 0 156.795 0C168.165 0 173.925 6.465 179.01 12.17C183.71 17.445 187.765 22 195.995 22V29H196Z" fill="#DC2035"/></svg>
                    </div>
                ) }
                    <div className="image-col column">
                        { vidOrImg === 'image' && (
                            <ImageComp
                                id={ media.id }
                                source={ media.srcSet.large }
                                updateImageAttr={ updateImageAttr }
                                alt={ media.alt }
                            />
                        ) }
                        { vidOrImg === 'video' && (
                            <Fragment>
                                <MediaUpload
                                    onSelect={ updateVideoAttr }
                                    allowedTypes={ [ 'video' ] }
                                    value={ videoID }
                                    render={ ( { open } ) => (
                                        <Button className="button" onClick={ open }>
                                            { __( 'Upload/Change Video', 'red-egg' ) }
                                        </Button>
                                    ) }
                                />
                                { videoID && (
                                    <video className="hero-asset" playsInline poster={ videothumb.url }>
                                        <source src={ videoURL } className="source" type="video/mp4" />
                                    </video>
                                ) }
                            </Fragment>
                        ) }
                    </div>
                    <div className="content-columns column">
                        <div className="wrap">
                            <InnerBlocks
                                template={ template }
                                allowedBlocks={ allowBlocks }
                            />
                        </div>
                    </div>
                </div>
            </div>
        </Fragment>
    );
};

export default EditImageText;
